import{_ as a,c as s,o as n,a2 as t}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse(`{"title":"Questions fréquentes","description":"Réponses sur le prix, la confidentialité, les Mac pris en charge, les dossiers, les langues et la restauration d'un achat.","frontmatter":{"title":"Questions fréquentes","description":"Réponses sur le prix, la confidentialité, les Mac pris en charge, les dossiers, les langues et la restauration d'un achat."},"headers":[],"relativePath":"fr/guide/faq.md","filePath":"fr/guide/faq.md","lastUpdated":1794296122000}`),i={name:"fr/guide/faq.md"};function r(o,e,u,l,c,d){return n(),s("div",null,[...e[0]||(e[0]=[t('<h1 id="questions-frequentes" tabindex="-1">Questions fréquentes <a class="header-anchor" href="#questions-frequentes" aria-label="Permalink to &quot;Questions fréquentes&quot;">​</a></h1><h3 id="qdiff-est-il-gratuit" tabindex="-1">qDiff est-il gratuit ? <a class="header-anchor" href="#qdiff-est-il-gratuit" aria-label="Permalink to &quot;qDiff est-il gratuit ?&quot;">​</a></h3><p>Oui. Toutes les comparaisons, toutes les vues et tous les exports fonctionnent sans paiement. La version gratuite affiche seulement une petite marque « sans licence » dans la barre d&#39;onglets. Un achat unique la retire et inclut les futures fonctions premium. Il n&#39;y a ni abonnement ni publicité.</p><h3 id="l-achat-debloque-t-il-des-fonctionnalites" tabindex="-1">L&#39;achat débloque-t-il des fonctionnalités ? <a class="header-anchor" href="#l-achat-debloque-t-il-des-fonctionnalites" aria-label="Permalink to &quot;L&#39;achat débloque-t-il des fonctionnalités ?&quot;">​</a></h3><p>Non, toutes les fonctionnalités sont déjà disponibles. L&#39;achat retire la marque. Si nous ajoutons des fonctions premium plus tard, elles rejoindront le même achat unique plutôt qu&#39;un nouveau produit.</p><h3 id="comment-restaurer-mon-achat" tabindex="-1">Comment restaurer mon achat ? <a class="header-anchor" href="#comment-restaurer-mon-achat" aria-label="Permalink to &quot;Comment restaurer mon achat ?&quot;">​</a></h3><p>Ouvrez <strong>Réglages → Premium</strong> et choisissez <strong>Restaurer les achats</strong>. Les achats sont liés à votre Apple ID et fonctionnent donc aussi sur vos autres Mac.</p><h3 id="quels-mac-sont-pris-en-charge" tabindex="-1">Quels Mac sont pris en charge ? <a class="header-anchor" href="#quels-mac-sont-pris-en-charge" aria-label="Permalink to &quot;Quels Mac sont pris en charge ?&quot;">​</a></h3><p>macOS 12 ou version ultérieure, sur les Mac à puce Apple et les Mac Intel. Consultez la <a href="./download.html#system-requirements">configuration requise</a>.</p><h3 id="ai-je-besoin-d-un-compte-ou-d-une-connexion-internet" tabindex="-1">Ai-je besoin d&#39;un compte ou d&#39;une connexion Internet ? <a class="header-anchor" href="#ai-je-besoin-d-un-compte-ou-d-une-connexion-internet" aria-label="Permalink to &quot;Ai-je besoin d&#39;un compte ou d&#39;une connexion Internet ?&quot;">​</a></h3><p>Non. qDiff fonctionne hors ligne, ne demande aucune connexion et n&#39;a aucun service en arrière-plan. Il ouvre uniquement les fichiers et les dossiers que vous choisissez.</p><h3 id="peut-il-comparer-des-dossiers-entiers-et-des-archives" tabindex="-1">Peut-il comparer des dossiers entiers et des archives ? <a class="header-anchor" href="#peut-il-comparer-des-dossiers-entiers-et-des-archives" aria-label="Permalink to &quot;Peut-il comparer des dossiers entiers et des archives ?&quot;">​</a></h3><p>Oui. Les dossiers s&#39;ouvrent en arborescence avec des filtres par état et des actions de copie et de synchronisation. Une archive .zip ou .tar peut être comparée comme un dossier, sans décompression.</p><h3 id="qu-en-est-il-des-images-et-des-fichiers-non-textuels" tabindex="-1">Qu&#39;en est-il des images et des fichiers non textuels ? <a class="header-anchor" href="#qu-en-est-il-des-images-et-des-fichiers-non-textuels" aria-label="Permalink to &quot;Qu&#39;en est-il des images et des fichiers non textuels ?&quot;">​</a></h3><p>Les images peuvent être vues côte à côte ou en superposition. Les fichiers qui ne sont pas du texte brut peuvent être comparés jusque dans les moindres détails. Consultez <a href="./more.html">d&#39;autres façons de comparer</a>.</p><h3 id="allez-vous-envoyer-ou-analyser-mes-fichiers" tabindex="-1">Allez-vous envoyer ou analyser mes fichiers ? <a class="header-anchor" href="#allez-vous-envoyer-ou-analyser-mes-fichiers" aria-label="Permalink to &quot;Allez-vous envoyer ou analyser mes fichiers ?&quot;">​</a></h3><p>Non. Rien n&#39;est collecté, suivi ni synchronisé. L&#39;explication complète figure dans la <a href="./../privacy/">Politique de confidentialité</a>.</p><h3 id="l-interface-est-elle-disponible-en-francais-et-dans-d-autres-langues" tabindex="-1">L&#39;interface est-elle disponible en français et dans d&#39;autres langues ? <a class="header-anchor" href="#l-interface-est-elle-disponible-en-francais-et-dans-d-autres-langues" aria-label="Permalink to &quot;L&#39;interface est-elle disponible en français et dans d&#39;autres langues ?&quot;">​</a></h3><p>Oui — anglais, chinois simplifié, chinois traditionnel, japonais, allemand, espagnol et français — avec une apparence claire et sombre.</p><h3 id="quelque-chose-ne-fonctionne-pas-que-dois-je-faire" tabindex="-1">Quelque chose ne fonctionne pas. Que dois-je faire ? <a class="header-anchor" href="#quelque-chose-ne-fonctionne-pas-que-dois-je-faire" aria-label="Permalink to &quot;Quelque chose ne fonctionne pas. Que dois-je faire ?&quot;">​</a></h3><p><a href="./support.html">Contactez-nous</a> en indiquant votre version de macOS et une brève description de ce qui s&#39;est passé. Une capture d&#39;écran aide beaucoup.</p>',21)])])}const f=a(i,[["render",r]]);export{p as __pageData,f as default};
